python3 << 'EOF'
import re

with open('/app/resources/treasury_bulletin_1970_06_page_89.txt', 'r') as f:
    content = f.read()

rows = re.findall(r'<tr>.*?</tr>', content, re.DOTALL)
months = ['Jan.', 'Feb.', 'Mar.', 'Apr.', 'May', 'June', 'July', 'Aug.', 'Sept.', 'Oct.', 'Nov.', 'Dec.']

data = []
for row in rows:
    cells = re.findall(r'<td[^>]*>(.*?)</td>', row, re.DOTALL)
    if cells and cells[0] in months:
        clean = []
        for c in cells:
            c = re.sub(r'<[^>]+>', '', c).strip()
            c = re.sub(r'\s*[\d]/', '', c).strip()
            clean.append(c)
        data.append(clean)

# Calculate spreads properly
def fmt(val):
    if val is None:
        return 'NA'
    return f"{val:.2f}"

print("Computing spreads (Corporate Aa - Treasury) for each group:")
for i in range(0, 36, 12):
    print(f"\n=== Rows {i}-{i+11} ===")
    for j in range(12):
        row_idx = i + j
        if row_idx < len(data):
            row = data[row_idx]
            month = row[0]
            spreads = []
            for col_idx in [[1,2], [4,5], [7,8], [10,11]]:
                t = row[col_idx[0]]
                a = row[col_idx[1]]
                if t and a:
                    try:
                        spread = float(a) - float(t)
                        spreads.append(spread)
                    except:
                        spreads.append(None)
                else:
                    spreads.append(None)
            print(f"{month}: G1={fmt(spreads[0])}, G2={fmt(spreads[1])}, G3={fmt(spreads[2])}, G4={fmt(spreads[3])}")
